import pathlib,json,ipaddress,tempfile,os
def build():
    source=pathlib.Path('subnets.json');output=pathlib.Path('plan.json')
    if source.is_symlink() or output.is_symlink() or (output.exists() and not output.is_file()):raise ValueError('regular files required')
    if source.stat().st_size>65536:raise ValueError('input too large')
    rows=json.loads(source.read_text())
    if not isinstance(rows,list) or len(rows)>128:raise ValueError('expected at most 128 subnets')
    networks=[];result=[]
    for row in rows:
        if not isinstance(row,dict) or set(row)!={'cidr','mode'}:raise ValueError('row schema')
        if not isinstance(row['cidr'],str) or not isinstance(row['mode'],str):raise ValueError('text fields')
        network=ipaddress.ip_network(row['cidr'],strict=True)
        if network.version!=4:raise ValueError('IPv4 only')
        if any(network.overlaps(other) for other in networks):raise ValueError('overlapping inventory')
        networks.append(network)
        mode=row['mode'];length=network.prefixlen;total=network.num_addresses
        if mode=='lan' and length<=30:first=int(network.network_address)+1;count=total-2
        elif mode=='point_to_point' and length==31:first=int(network.network_address);count=2
        elif mode=='host' and length==32:first=int(network.network_address);count=1
        else:raise ValueError('mode/prefix mismatch')
        result.append({'cidr':str(network),'mode':mode,'address_count':total,'usable_count':count,
                       'first':str(ipaddress.IPv4Address(first)),'last':str(ipaddress.IPv4Address(first+count-1))})
    with tempfile.NamedTemporaryFile('w',dir='.',delete=False,encoding='utf-8') as handle:
        temporary=handle.name;json.dump(result,handle,sort_keys=True);handle.flush();os.fsync(handle.fileno())
    try:os.replace(temporary,output)
    finally:
        if os.path.exists(temporary):os.unlink(temporary)
    return result
```

点对点/31与单主机/32必须结合用途处理，LAN中的网络/广播排除规则不能无条件套用。清单重叠检查可在真正发布地址配置前拦截规划冲突，但不检查远端设备或现网已分配地址。

原题原理说明：
/27 留5位主机位，共32个地址；传统普通广播子网通常扣除网络和广播地址，剩30个。/31 点到点链路与 /32 主机路由语义不同，云平台也可能额外保留地址。计算可分配数量前应明确链路类型和提供商规则。

